messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Two-car race – three.js</title>
  <style>
    body { margin: 0; overflow: hidden; background-color: #111; }
    #info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      font-family: 'Segoe UI', Tahoma, sans-serif;
      font-size: 18px;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
      pointer-events: none;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="info">🏁 RED wins • BLUE leads early • loop</div>

  <script type="importmap">
    {
      "imports": {
        "three": "./three.module.js"
      }
    }
  </script>

  <script type="module">
    import * as THREE from 'three';

    // ----- setup scene, camera, renderer -----
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    // camera – positioned to see the whole track
    const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(10, 6, 18);
    camera.lookAt(0, 0, 8);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // ----- lights -----
    const ambientLight = new THREE.AmbientLight(0x404060);
    scene.add(ambientLight);

    const mainLight = new THREE.DirectionalLight(0xfff5e6, 1.2);
    mainLight.position.set(10, 20, 10);
    mainLight.castShadow = true;
    mainLight.shadow.mapSize.width = 1024;
    mainLight.shadow.mapSize.height = 1024;
    const d = 30;
    mainLight.shadow.camera.left = -d;
    mainLight.shadow.camera.right = d;
    mainLight.shadow.camera.top = d;
    mainLight.shadow.camera.bottom = -d;
    mainLight.shadow.camera.near = 1;
    mainLight.shadow.camera.far = 50;
    scene.add(mainLight);

    // fill light
    const fillLight = new THREE.PointLight(0x4466ff, 0.3);
    fillLight.position.set(-5, 5, 10);
    scene.add(fillLight);

    // ----- ground -----
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x4a5c6e,
      roughness: 0.7,
      metalness: 0.1,
    });
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(30, 40), groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.3;
    ground.receiveShadow = true;
    scene.add(ground);

    // track markings – simple lane lines
    const lineMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, emissive: 0x222222 });
    for (let z = -5; z < 25; z += 1.2) {
      const line = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.02, 0.6), lineMat);
      line.position.set(0, 0.01, z);
      scene.add(line);
    }

    // ----- finish line (visible) -----
    const finishMat = new THREE.MeshStandardMaterial({
      color: 0xffaa00,
      emissive: 0x442200,
      roughness: 0.4,
    });
    const finishLine = new THREE.Mesh(new THREE.BoxGeometry(4.4, 0.4, 0.3), finishMat);
    finishLine.position.set(0, 0.05, 20);
    finishLine.castShadow = true;
    finishLine.receiveShadow = true;
    scene.add(finishLine);

    // checkered pattern on finish line
    const checkerMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 });
    for (let i = -2; i <= 2; i += 0.5) {
      const cell = new THREE.Mesh(new THREE.BoxGeometry(0.45, 0.3, 0.1), checkerMat);
      cell.position.set(i, 0.25, 20.15);
      cell.castShadow = false;
      cell.receiveShadow = true;
      scene.add(cell);
    }

    // ----- cars: red and blue -----
    function createCar(color, isRed) {
      const group = new THREE.Group();

      // body
      const bodyMat = new THREE.MeshStandardMaterial({
        color: color,
        roughness: 0.3,
        metalness: 0.7,
      });
      const body = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.4, 2.4), bodyMat);
      body.position.y = 0.15;
      body.castShadow = true;
      body.receiveShadow = true;
      group.add(body);

      // cabin (top)
      const cabinMat = new THREE.MeshStandardMaterial({
        color: isRed ? 0xcc3333 : 0x3366cc,
        roughness: 0.4,
        metalness: 0.2,
      });
      const cabin = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.25, 1.2), cabinMat);
      cabin.position.set(0, 0.45, -0.3);
      cabin.castShadow = true;
      cabin.receiveShadow = true;
      group.add(cabin);

      // windscreen
      const glassMat = new THREE.MeshStandardMaterial({
        color: 0x88ccff,
        transparent: true,
        opacity: 0.6,
        roughness: 0.1,
        metalness: 0.1,
      });
      const windshield = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.22, 0.1), glassMat);
      windshield.position.set(0, 0.45, 0.75);
      windshield.castShadow = true;
      group.add(windshield);

      // rear window
      const rear = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.22, 0.1), glassMat);
      rear.position.set(0, 0.45, -1.35);
      rear.castShadow = true;
      group.add(rear);

      // wheels
      const wheelMat = new THREE.MeshStandardMaterial({
        color: 0x222222,
        roughness: 0.9,
      });
      const wheelPositions = [
        [-0.7, 0.1, 0.9],
        [0.7, 0.1, 0.9],
        [-0.7, 0.1, -0.9],
        [0.7, 0.1, -0.9],
      ];
      for (const pos of wheelPositions) {
        const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.15, 16), wheelMat);
        wheel.rotation.x = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        wheel.castShadow = true;
        wheel.receiveShadow = true;
        group.add(wheel);
      }

      // spoiler (small)
      const spoilerMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
      const spoiler = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.05, 0.2), spoilerMat);
      spoiler.position.set(0, 0.35, -1.3);
      spoiler.castShadow = true;
      group.add(spoiler);

      return group;
    }

    // create cars
    const redCar = createCar(0xff3300, true);
    redCar.position.set(-1.2, 0, -2); // start behind
    scene.add(redCar);

    const blueCar = createCar(0x2266ff, false);
    blueCar.position.set(1.2, 0, 2);  // start ahead
    scene.add(blueCar);

    // ----- animation parameters -----
    // race runs from z = -3 to finish at z = 20
    const START_Z = -3;
    const FINISH_Z = 20;
    const RACE_LENGTH = FINISH_Z - START_Z; // 23

    // blue car: faster early, then red overtakes
    // we define progress (0..1) for each car with a nonlinear mapping
    // red car accelerates later

    let raceTime = 0;
    const RACE_DURATION = 4.8; // seconds per loop

    // ----- helpers -----
    function resetRace() {
      raceTime = 0;
      // reset positions
      redCar.position.z = START_Z;
      blueCar.position.z = START_Z + 4; // blue leads early
    }

    // initial reset
    resetRace();

    // ----- animation loop -----
    function animate() {
      const dt = 0.016; // ~60fps
      raceTime += dt;

      // loop race
      if (raceTime > RACE_DURATION) {
        raceTime -= RACE_DURATION;
        // reset positions immediately
        redCar.position.z = START_Z;
        blueCar.position.z = START_Z + 4;
      }

      // compute progress (0..1) for each car
      const t = Math.min(raceTime / RACE_DURATION, 1.0);

      // red car: slow at start, fast at end (overtake mid-race)
      // use power curve: redProgress = t^1.8 * 1.2 (clamped)
      let redProgress = Math.pow(t, 1.6) * 1.2;
      if (redProgress > 1.0) redProgress = 1.0;

      // blue car: fast early, then fades
      let blueProgress = 1.0 - Math.pow(1.0 - t, 1.8) * 0.9;
      if (blueProgress > 1.0) blueProgress = 1.0;

      // map to Z positions
      const redZ = START_Z + redProgress * RACE_LENGTH;
      const blueZ = START_Z + blueProgress * RACE_LENGTH;

      // ensure blue stays ahead early, red overtakes at ~t=0.55
      // we can adjust curve shapes – but let's enforce a realistic overtake:
      // if t < 0.3, blue leads by at least 2 units
      // after t ~0.55 red passes
      // we'll blend with a manual override for dramatic effect
      let redFinal = redZ;
      let blueFinal = blueZ;

      // manual overtaking logic:
      const phase = t;
      if (phase < 0.25) {
        // blue stays ahead
        blueFinal = START_Z + 4 + phase * 6;
        redFinal = START_Z + phase * 2;
      } else if (phase < 0.5) {
        // red catches up
        const catchUp = (phase - 0.25) / 0.25;
        redFinal = START_Z + 2 + catchUp * 12;
        blueFinal = START_Z + 5.5 + catchUp * 4;
      } else if (phase < 0.75) {
        // overtake
        const overtake = (phase - 0.5) / 0.25;
        redFinal = START_Z + 10 + overtake * 10;
        blueFinal = START_Z + 8 + overtake * 3;
        // red passes around 0.6
      } else {
        // red wins
        const finalPhase = (phase - 0.75) / 0.25;
        redFinal = START_Z + 18 + finalPhase * 5;
        blueFinal = START_Z + 10 + finalPhase * 2;
      }

      // clamp to finish
      if (redFinal > FINISH_Z) redFinal = FINISH_Z;
      if (blueFinal > FINISH_Z - 0.5) blueFinal = FINISH_Z - 0.5;

      // apply positions
      redCar.position.z = redFinal;
      blueCar.position.z = blueFinal;

      // slight y wobble for visual
      redCar.position.y = 0.05 * Math.sin(raceTime * 6 + 1.2);
      blueCar.position.y = 0.05 * Math.sin(raceTime * 6);

      // rotate wheels
      const wheelRotation = raceTime * 4;
      redCar.children.forEach((child, i) => {
        if (i >= 4 && i <= 7) { // wheel indices 4-7
          child.rotation.x += dt * 6;
        }
      });
      blueCar.children.forEach((child, i) => {
        if (i >= 4 && i <= 7) {
          child.rotation.x += dt * 6;
        }
      });

      // camera follows action – keep both cars in view
      const midZ = (redFinal + blueFinal) / 2;
      const avgZ = Math.max(0, Math.min(22, midZ));
      camera.position.z = avgZ + 10;
      camera.position.x = 3.5;
      camera.position.y = 5 + 0.3 * Math.sin(raceTime * 0.8);
      camera.lookAt(avgZ * 0.3, 0.5, avgZ + 2);

      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    // ----- resize handler -----
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```
